MultiLanguageItemData['mx'][22557] = {name = "[q2]Fórmula: encantar arma: maestro de batalla", additional_info = "[q2]Uso: Te enseña a aplicar el encantamiento Maestro de batalla.\n[q2]Encanta un arma cuerpo a cuerpo de forma permanente para que en ocasiones restaure 3797 p. de salud a los miembros del grupo cercanos al realizar ataques cuerpo a cuerpo. No se puede aplicar a objetos de nivel superior a 320.\nRequiere Encantamiento de Terrallende (60)\nPrecio de venta:"}
MultiLanguageItemData['mx'][22558] = {name = "[q2]Fórmula: encantar arma: oleada de hechizos", additional_info = "[q2]Uso: Te enseña a aplicar el encantamiento Oleada de hechizos.\n[q2]Encanta un arma cuerpo a cuerpo de forma permanente para que tus hechizos a veces restauren 3750 p. de maná a los miembros del grupo cercanos. No se puede aplicar a objetos de nivel superior a 320.\nRequiere Encantamiento de Terrallende (60)\nPrecio de venta:"}
MultiLanguageItemData['mx'][22559] = {name = "[q3]Fórmula: encantar arma: mangosta", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a aplicar el encantamiento Mangosta.\n[q2]Encanta un arma cuerpo a cuerpo de forma permanente para que en ocasiones aumente 24 p. la agilidad y 6 p. la celeridad. No se puede aplicar a objetos de nivel superior a 320.\nRequiere Encantamiento de Terrallende (75)\nPrecio de venta:"}
MultiLanguageItemData['mx'][22560] = {name = "[q3]Fórmula: encantar arma: Fuego solar", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a aplicar el encantamiento Fuego solar.\n[q2]Encanta de forma permanente un arma cuerpo a cuerpo para aumentar 10 p. el poder con hechizos arcanos y de fuego. No se puede aplicar a objetos de nivel superior a 320.\nRequiere Encantamiento de Terrallende (75)\nPrecio de venta:"}
MultiLanguageItemData['mx'][22561] = {name = "[q3]Fórmula: encantar arma: escarcha de alma", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a aplicar el encantamiento Escarcha de alma.\n[q2]Encanta de forma permanente un arma cuerpo a cuerpo para aumentar 10 p. el poder con hechizos de las sombras y de escarcha. No se puede aplicar a objetos de nivel superior a 320.\nRequiere Encantamiento de Terrallende (75)\nPrecio de venta:"}
MultiLanguageItemData['mx'][22562] = {name = "Fórmula: aceite de maná excelente", additional_info = "[q2]Uso: Te enseña a hacer aceite de maná excelente.\n[q2]Crea aceite de maná excelente.\nRequiere Encantamiento de Terrallende (10)\nPrecio de venta: \nAceite de maná excelente\n[q2]Uso: Aplica aceite de maná excelente a tu arma, lo que aumenta 11 p. la versatilidad. Â El efecto dura 1 hora. Â No se puede aplicar a objetos de nivel superior a 320.\n5 cargas\nPrecio de venta:\nRequiere Polvo Arcano (3), Flor abisal , Vial de cristal"}
MultiLanguageItemData['mx'][22563] = {name = "Fórmula: aceite de zahorí excelente", additional_info = "[q2]Uso: Te enseña a hacer aceite de zahorí excelente.\n[q2]Crea aceite de zahorí excelente.\nRequiere Encantamiento de Terrallende (40)\nPrecio de venta: \nAceite de zahorí excelente\n[q2]Uso: Aplica aceite de zahorí excelente a tu arma, lo que aumenta 17 p. el intelecto. El efecto dura 1 hora. No se puede aplicar a objetos de nivel superior a 320.\n5 cargas\nPrecio de venta:\nRequiere Polvo Arcano (3), Vid pesadilla , Vial de cristal"}
MultiLanguageItemData['mx'][22564] = {name = "Fórmula: polvo Arcano", additional_info = "[q2]Uso: Te enseña a convertir un cristal Arcano en polvo Arcano.\n[q2]Transforma un cristal Arcano en polvo Arcano.\nRequiere Encantamiento de Terrallende (25)\nPrecio de venta: \nPolvo Arcano\nMaterial de profesión\nRequiere Cristal Arcano"}
