MultiLanguageItemData['mx'][24000] = {name = "Fórmula: encantar brazales: sanación excelente", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a aplicar el encantamiento Sanación excelente en brazales.\n[q2]Encanta los brazales de forma permanente para que aumente 4 p. el poder con hechizos. No se puede aplicar a objetos de nivel superior a 376.\nRequiere Encantamiento de Terrallende (25)\nRequiereThrallmar\n: Amistoso\nPrecio de venta:"}
MultiLanguageItemData['mx'][24001] = {name = "Receta: elixir de agilidad sublime", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer un elixir de agilidad sublime.\nRequiere Alquimia de Terrallende (30)\nRequiereThrallmar\n: Honorable\nPrecio de venta: \nElixir de agilidad sublime\n[q2]Uso: Aumenta tu agilidad 10 p. y tu golpe crítico 4 p. durante 1 h. Elixir de batalla. (3 Seg Reutilización)\nPrecio de venta:\nRequiere Teropiña , Pasto vil (2), Vial de cristal"}
MultiLanguageItemData['mx'][24002] = {name = "Diseño: punta de escudo de acero vil", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a hacer una punta de escudo de acero vil.\nRequiere Herrería de Terrallende (60)\nRequiereThrallmar\n: Exaltado\nPrecio de venta: \n[q2]Punta de escudo de acero vil\n[q2]Uso: Añade a tu escudo una punta de acero vil que inflige 3 p. de daño cuando bloqueas un ataque. No se puede aplicar a objetos de nivel superior a 0.\nPrecio de venta: \nRequiere Barra de acero vil (4), Fuego primigenio (4), Tierra primigenia (4)"}
MultiLanguageItemData['mx'][24003] = {name = "Fórmula: encantar pechera: estadísticas excepcionales", additional_info = "Se liga al recogerlo\n[q2]Uso: Te enseña a aplicar el encantamiento Estadísticas excepcionales en armaduras de torso.\n[q2]Encanta una pieza de armadura de torso de forma permanente para aumentar 534 p. todas las estadísticas. No se puede aplicar a objetos de nivel superior a 376.\nRequiere Encantamiento de Terrallende (45)\nRequiereThrallmar\n: Reverenciado\nPrecio de venta:"}
