MultiLanguageItemData['mx'][44224] = {name = "[q4]Riendas del oso de guerra negro", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\n\n\n[q]\"Esta formidable montura se compra con la sangre de los líderes de la Alianza, pero lo habrás matado gratuitamente.\"\nLogro:\n¡Por la Horda!\nCategoría:\nJugador contra Jugador"}
MultiLanguageItemData['mx'][44225] = {name = "[q4]Riendas del oso marrón acorazado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"La agilidad de esta montura osuna es mejorada por su armadura pesada, imbuida con magia de Kirin Tor.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
MultiLanguageItemData['mx'][44226] = {name = "[q4]Riendas del oso marrón acorazado", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Cuando grites \"¡Por la Horda!\", sonará mucho más intimidante sobre un oso bien acorazado que arremete contra la Alianza a toda velocidad.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
MultiLanguageItemData['mx'][44228] = {name = "Especias de bebé", additional_info = "Se liga al recogerlo\n[q2]Uso: Reduce el tamaño del objetivo un 50% y lo convierte en un bebé. (10 Seg Reutilización)\nPrecio de venta:"}
MultiLanguageItemData['mx'][44229] = {name = "Riendas de jinete del viento prestado", additional_info = "Se liga al recogerlo\nÚnico\nMontura\n[q0](Ligado a la cuenta)\n[q2]Uso: Invoca y retira a un jinete del viento prestado que se puede montar. Esta montura solo se puede invocar en Las Cumbres Tormentosas, Corona de Hielo y Cuenca de Sholazar. (3 Seg Reutilización)\nRequiere nivel 1 - 80 ( 80)"}
MultiLanguageItemData['mx'][44230] = {name = "[q4]Riendas del mamut lanudo", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Descendiente directo del progenitor original de la raza de los mamuts, los mamuts lanudos son considerados como más feroces y salvajes que sus primos de pelaje corto.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
MultiLanguageItemData['mx'][44231] = {name = "[q4]Riendas del mamut lanudo", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Este tipo de mamut salvaje no se cría para montarlos. La mayoría de los mamuts lanudos son capturados en hábitats salvajes y son amaestrados por sus jinetes, lo que resulta en una montura feroz y astuta.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
MultiLanguageItemData['mx'][44234] = {name = "[q4]Riendas del mamut de tundra de viajero", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar una montura para tres personas con vendedores.\n[q2]Llama al mamut de tundra de viajero, ¡con dos compañeros!\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Tanto los jinetes como los mercantes solo confían en este fuerte y veloz mamut para que los lleve a salvo a través de la helada tundra.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
MultiLanguageItemData['mx'][44235] = {name = "[q4]Riendas del mamut de tundra de viajero", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar una montura para tres personas con vendedores.\n[q2]Llama al mamut de tundra de viajero, ¡con dos compañeros!\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\n\n\n[q]\"Los manuscritos antiguos muestran a los mercantes viajando a través de la tundra congelada con estas colosales bestias, lo que llevó a los estudiosos a creer que eran las primeras monturas domesticadas.\"\nVendedor:\nMei Francis\nZona:\nBosque Canto de Cristal\nCosto:"}
