MultiLanguageItemData['mx'][46743] = {name = "[q4]Raptor morado presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Viejos aliados de los trols, estos cazadores de la jungla crean un vínculo especial con sus amos. Se convierten en monturas, guardianes y amigos.\"\nVendedor:\nSamamba\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46744] = {name = "[q4]Sable de la luna presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Muchos elfos de la noche veneran a estas orgullosas monturas porque su deslumbrante pelaje simboliza a la diosa de la luna, Elune.\"\nVendedor:\nRook Puñohalcón\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46745] = {name = "[q4]Gran elekk rojo", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nYa conocido\nPrecio de venta:\n[q]\"Nunca vistos en Nagrand, los primeros cachorros de elekk rojo nacieron en Azeroth tras la llegada de Exodar. Algunos criadores tienen la teoría de que su color único es de alguna manera provocado por la misma radiación que se propagó por la Isla Bruma de Sangre.\"\nVendedor:\nIrisee\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46746] = {name = "[q4]Caballo de guerra esquelético blanco", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Cuando los héroes caídos se levantan como no muertos, también lo hacen sus caballos.\"\nVendedor:\nEliza Killian\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46747] = {name = "[q4]Turbozancudo", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El espejo no es para que puedas mirar atrás, sino para que tus enemigos puedan ver algo más que tus tubos de escape. -Rillie Ejeloco\"\nVendedor:\nRillie Ejeloco\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46748] = {name = "[q4]Carnero violeta presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"El cráneo grueso y huesudo del carnero de Barak Tor'ol y sus masivos cuernos lo hacen la montura ideal para arremeter contra grupos de enemigos acorazados.\"\nVendedor:\nDerrick Barba Berrenda\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46749] = {name = "[q4]Lobo burdeos presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nPrecio de venta:\n[q]\"Uno no domestica a los lobos de la Horda, se hace amigo de ellos.\"\nVendedor:\nFreka Hacha de Sangre\nZona:\nCorona de Hielo\nCosto:"}
