MultiLanguageItemData['mx'][46758] = {name = "[q4]Corcel gris presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereVentormenta\n: Exaltado\nPrecio de venta:\n[q]\"Un veterano de algunas de las batallas más duras luchadas por la Cruzada Argenta.\"\nVendedor:\nCabo Arthur Flew\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46759] = {name = "[q4]Sable de la luna presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Alianza\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereDarnassus\n: Exaltado\nPrecio de venta:\n[q]\"Muchos elfos de la noche veneran a estas orgullosas monturas porque su deslumbrante pelaje simboliza a la diosa de la luna, Elune.\"\nVendedor:\nRook Puñohalcón\nZona:\nCorona de Hielo\nCosto:"}
MultiLanguageItemData['mx'][46760] = {name = "[q4]Raptor morado presto", additional_info = "Se liga al recogerlo\nMontura\n[q0](Ligado a la cuenta)\nRequiere cualquier raza de la Horda\n[q2]Uso: Te enseña a invocar esta montura.\nRequiere nivel 1 - 80 ( 80)\nRequiereAprendiz jinete\nRequiereTrols Lanza Negra\n: Exaltado\nPrecio de venta:\n[q]\"Viejos aliados de los trols, estos cazadores de la jungla crean un vínculo especial con sus amos. Se convierten en monturas, guardianes y amigos.\"\nVendedor:\nSamamba\nZona:\nCorona de Hielo\nCosto:"}
